UPDATE TASK /* QueryID : com.demo.proworks.task.updateTask */
SET
BOARD_ID = #{boardId}
, PROJECT_USER_ID = #{projectUserId}
 , PROJECT_REPO_ID = #{projectRepoId} 
, TASK_TITLE = #{taskTitle}
, PRIORITY = #{priority}
, START_DATE = #{startDate}
, END_DATE = #{endDate}
, TAGS = #{tags}
WHERE TASK_ID = #{taskId}

