DELETE FROM TASK /* QueryID : com.demo.proworks.task.deleteTaskByProjectId */
WHERE BOARD_ID IN (
	SELECT BOARD_ID
	FROM BOARD
	WHERE PROJECT_ID = #{projectId}
)
